#include <linux/compat.h>
#include <linux/uaccess.h>
#include <linux/ioctl.h>

int set_subtitle_palette(unsigned int fd, unsigned int cmd, struct compat_video_spu_palette __user *up) {
    int ret;
    struct compat_video_spu_palette __user *native_up;
    unsigned int len;

    if (get_user(len, &up->len))
        return -EFAULT;

    native_up = compat_alloc_user_space(sizeof(*native_up));
    if (!native_up)
        return -ENOMEM;

    if (copy_from_user(native_up, up, sizeof(*native_up)))
        return -EFAULT;

    ret = ioctl(fd, cmd, native_up);
    if (ret < 0)
        return ret;

    return 0;
}

