#include <linux/compat.h>
#include <linux/uaccess.h>
#include <linux/ioctl.h>

int set_subtitle_palette(unsigned int fd, unsigned int cmd, struct compat_video_spu_palette __user *up) {
    struct compat_video_spu_palette palette;
    int i, ret;

    for (i = 0; i < 16; i++) {
        if (copy_from_user(&palette.entries[i], &up->entries[i], sizeof(palette.entries[i])))
            return -EFAULT;
    }

    palette.length = 16;

    if (copy_from_user(&palette.length, &up->length, sizeof(palette.length)))
        return -EFAULT;

    ret = ioctl(fd, cmd, &palette);

    return ret;
}

