#include <linux/ioctl.h>
#include <linux/compat.h>
#include <linux/uaccess.h>

int set_subtitle_palette(unsigned int fd, unsigned int cmd, struct compat_video_spu_palette __user *up) {
    struct compat_video_spu_palette __user *palette;
    int err;
    unsigned int len;

    if (get_user(len, &up->length))
        return -EFAULT;

    palette = kmalloc(sizeof(struct compat_video_spu_palette), GFP_KERNEL);
    if (!palette)
        return -ENOMEM;

    if (copy_from_user(palette, up, sizeof(struct compat_video_spu_palette))) {
        kfree(palette);
        return -EFAULT;
    }

    err = ioctl(fd, cmd, palette);

    kfree(palette);
    return err;
}
